#!/usr/bin/env bash
# Run every step grader against the current tree. Generated by tools/generate.mjs.
#
#   .labex/run-all.sh            every step, in order
#   .labex/run-all.sh 1 20       steps 1..20
# With ./lab solve --step N applied first, steps that are build/run/test pass;
# steps that need a live server or process report FAIL truthfully.
set -uo pipefail
cd "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
first=${1:-1}
last=${2:-84}
pass=0; fail=0; skip=0
for n in $(seq "$first" "$last"); do
  if ./.labex/verify_step"$n".sh >/tmp/lab-step-"$n".log 2>&1; then
    if grep -q 'nothing to grade' /tmp/lab-step-"$n".log; then
      printf '%3d SKIP  %s\n' "$n" "$(head -2 /tmp/lab-step-"$n".log | tail -1)"
      skip=$((skip + 1))
    else
      printf '%3d PASS  %s\n' "$n" "$(head -2 /tmp/lab-step-"$n".log | tail -1)"
      pass=$((pass + 1))
    fi
  else
    printf '%3d FAIL  %s\n' "$n" "$(head -2 /tmp/lab-step-"$n".log | tail -1)"
    fail=$((fail + 1))
  fi
done
echo "---- $pass passed, $fail failed, $skip skipped (steps $first-$last)"
[ "$fail" -eq 0 ]
